mapper.insert:
insert into PBC_TARGET_INFO(UUID, ACCOUNT, PBC_PROD_ID,INDENTIFY_MARK, HOLDER_NAME, HOLDER_TYPE, HOLD_DATE, CCY, QTY, AMOUNT,STATUS,UPDATE_TIME,CREATE_TIME,CREATE_USER,UPDATE_USER) select TEMP.* from (
SELECT #{item.uuid,jdbcType=CHAR} UUID, #{item.account,jdbcType=VARCHAR} ACCOUNT, #{item.pbcProdId,jdbcType=VARCHAR} PBC_PROD_ID, #{item.indentifyMark,jdbcType=VARCHAR} INDENTIFY_MARK, #{item.holderName,jdbcType=VARCHAR} HOLDER_NAME, #{item.holderType,jdbcType=VARCHAR} HOLDER_TYPE, #{item.holdDate,jdbcType=TIMESTAMP} HOLD_DATE, #{item.ccy,jdbcType=VARCHAR} CCY, #{item.qty,jdbcType=DECIMAL} QTY, #{item.amount,jdbcType=DECIMAL} AMOUNT, #{item.status,jdbcType=VARCHAR} STATUS, NOW() UPDATE_TIME, NOW() CREATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER FROM DUAL
) TEMP where not exists (select 1 from PBC_TARGET_INFO CII where CII.ACCOUNT = TEMP.ACCOUNT AND CII.INDENTIFY_MARK = TEMP.INDENTIFY_MARK and CII.HOLD_DATE = TEMP.HOLD_DATE); UPDATE PBC_TARGET_INFO as A, ( select TEMP.* from (
SELECT #{item.uuid,jdbcType=CHAR} UUID, #{item.account,jdbcType=VARCHAR} ACCOUNT, #{item.pbcProdId,jdbcType=VARCHAR} PBC_PROD_ID, #{item.indentifyMark,jdbcType=VARCHAR} INDENTIFY_MARK, #{item.holderName,jdbcType=VARCHAR} HOLDER_NAME, #{item.holderType,jdbcType=VARCHAR} HOLDER_TYPE, #{item.holdDate,jdbcType=TIMESTAMP} HOLD_DATE, #{item.ccy,jdbcType=VARCHAR} CCY, #{item.qty,jdbcType=DECIMAL} QTY, #{item.amount,jdbcType=DECIMAL} AMOUNT, #{item.status,jdbcType=VARCHAR} STATUS, NOW() UPDATE_TIME, NOW() CREATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER FROM DUAL
) TEMP ) AS B set A.HOLDER_NAME = B.HOLDER_NAME, A.HOLDER_TYPE = B.HOLDER_TYPE, A.CCY = B.CCY, A.QTY = B.QTY, A.AMOUNT = B.AMOUNT, A.UPDATE_TIME = B.UPDATE_TIME, A.UPDATE_USER = B.UPDATE_USER, A.STATUS = B.STATUS WHERE A.ACCOUNT = B.ACCOUNT AND A.INDENTIFY_MARK = B.INDENTIFY_MARK and A.HOLD_DATE = B.HOLD_DATE;
